 if(a==='phOpen'){px.fresh=true;px.id=value;px.screen='viewer';px.chrome=true;px.zoom=1;px.pan={x:0,y:0};px.info=false;px.more=false;px.from=px.tab==='search'&&!px.scope?'search':null;return again();}
 if(a==='phBack'){if(px.returnTo==='camera'){px.returnTo=null;px.screen='tabs';await phone.go('camera');return;}px.screen='tabs';px.info=false;px.more=false;return again();}
 if(a==='phNext'||a==='phPrev'){const list=px.from==='search'?find(phone,px.search):scopeList(phone,px),i=list.findIndex(m=>m.id===px.id),n=list[i+(a==='phNext'?1:-1)];if(n){px.fresh=true;px.id=n.id;px.zoom=1;px.pan={x:0,y:0};px.info=false;px.more=false;again();}return;}
 if(a==='phMore'){px.more=!px.more;px.info=false;return again();}
 if(a==='phInfo'){px.info=!px.info;px.more=false;return again();}
 if(a==='phFav'){const m=phone.media.find(q=>q.id===px.id);if(m){await patch(phone,[m.id],{favorite:!m.favorite});again();const h=phone.ctx.container.querySelector('[data-phone="phFav"]');h?.classList.add('pop');}return;}
 if(a==='phFavMany'){const ids=[...px.picked],all=ids.every(id=>phone.media.find(m=>m.id===id)?.favorite);await patch(phone,ids,{favorite:!all});px.select=false;px.picked.clear();return again();}
 if(a==='phPlay'){const v=host.querySelector('.pp-video');if(v){if(v.paused)v.play().catch(()=>phone.ctx.toast('This video could not be played.'));else v.pause();}return;}
 if(a==='phMute'){px.muted=!px.muted;const v=host.querySelector('.pp-video');if(v)v.muted=px.muted;if(button)button.innerHTML=ic(px.muted?'mute':'volume',19);return;}
 if(a==='phDelete'){const ids=targets(phone,px);if(ids.length){px.sheet={kind:'delete',ids};px.more=false;again();}return;}
 if(a==='phConfirmDelete'){const ids=px.sheet?.ids||[];px.sheet=null;if(px.screen==='viewer'){const list=scopeList(phone,px),i=list.findIndex(m=>m.id===px.id),next=list[i+1]||list[i-1];px.id=next?.id||null;px.fresh=true;if(!next)px.screen='tabs';}await patch(phone,ids,{deletedAt:Date.now()});px.select=false;px.picked.clear();return again();}
 if(a==='phRestore'||a==='phRestoreMany'){const ids=a==='phRestore'?[px.id]:[...px.picked];await patch(phone,ids,{deletedAt:null});px.select=false;px.picked.clear();px.screen='tabs';return again();}
 if(a==='phErase'||a==='phEraseMany'){const ids=a==='phErase'?[px.id]:[...px.picked];if(ids.length){px.sheet={kind:'erase',ids};again();}return;}
 if(a==='phConfirmErase'){const ids=px.sheet?.ids||[];px.sheet=null;for(const id of ids){forget(phone,id);try{await Media().remove(id);}catch(_){}}px.select=false;px.picked.clear();px.screen='tabs';await phone.loadMedia();return again();}
 if(a==='phEmpty'){px.sheet={kind:'empty'};return again();}
 if(a==='phConfirmEmpty'){px.sheet=null;for(const m of gone(phone)){forget(phone,m.id);try{await Media().remove(m.id);}catch(_){}}await phone.loadMedia();return again();}
 if(a==='phSheetClose'){px.sheet=null;return again();}
 if(a==='phShare'){const ids=targets(phone,px);if(ids.length){px.sheet={kind:'share',ids};px.more=false;again();}return;}
 if(a==='phSave'){const ids=targets(phone,px);px.sheet=null;px.more=false;let i=0;for(const id of ids){const m=phone.media.find(q=>q.id===id);if(m){setTimeout(()=>download(m.blob,nameOf(m)),i++*350);}}phone.ctx.toast(ids.length===1?'Saving to this device.':'Saving '+ids.length+' files to this device.');return again();}
 if(a==='phCopy'){const m=phone.media.find(q=>q.id===targets(phone,px)[0]);px.sheet=null;if(m){try{const img=await loadImage(m.blob),c=document.createElement('canvas');c.width=img.naturalWidth;c.height=img.naturalHeight;c.getContext('2d').drawImage(img,0,0);const png=await new Promise(res=>c.toBlob(res,'image/png'));await navigator.clipboard.write([new root.ClipboardItem({'image/png':png})]);phone.ctx.toast('Photo copied.');}catch(e){phone.ctx.toast('This browser did not allow copying the photo.');}}return again();}
