 if(a==='phAlbumAdd'){const ids=px.sheet?.ids||[];px.sheet=null;await patch(phone,ids,m=>({albums:[...new Set([...(m.albums||[]),value])]}));px.select=false;px.picked.clear();phone.ctx.toast('Added to the album.');return again();}
 if(a==='phNewAlbum'){px.sheet={kind:'name',ids:px.sheet?.ids||(px.select?[...px.picked]:[]),value:''};return again();}
 if(a==='phAlbumRename'){const al=(phone.data.albums||[]).find(q=>q.id===px.scope?.slice(6));if(al){px.sheet={kind:'name',rename:al.id,value:al.name};again();}return;}
 if(a==='phAlbumSave'){const name=(host.querySelector('#ppAlbumName')?.value||'').trim().slice(0,40),s=px.sheet||{};if(!name){phone.ctx.toast('Give the album a name.');return;}phone.data.albums??=[];if(s.rename){const al=phone.data.albums.find(q=>q.id===s.rename);if(al)al.name=name;px.sheet=null;}else{const id='album-'+Date.now().toString(36);phone.data.albums.push({id,name});const ids=s.ids||[];px.sheet=null;if(ids.length){await patch(phone,ids,m=>({albums:[...new Set([...(m.albums||[]),id])]}));px.select=false;px.picked.clear();}if(px.screen==='tabs'){px.tab='collections';px.scope='album:'+id;}}phone.save();return again();}
 if(a==='phAlbumMenu'){px.sheet={kind:'albumMenu'};return again();}
 if(a==='phAlbumRemoveItems'){px.sheet=null;px.select=true;px.albumRemove=true;px.picked.clear();phone.ctx.toast('Pick items, then press the album button to take them out of this album.');return again();}
 if(a==='phAlbumDelete'){const id=px.scope?.slice(6);px.sheet=null;phone.data.albums=(phone.data.albums||[]).filter(q=>q.id!==id);phone.save();const ids=live(phone).filter(m=>(m.albums||[]).includes(id)).map(m=>m.id);await patch(phone,ids,m=>({albums:(m.albums||[]).filter(q=>q!==id)}));px.scope=null;px.tab='collections';return again();}
