 if(a==='phEdit'){const m=phone.media.find(q=>q.id===px.id);if(!m)return;px.more=false;px.info=false;if(m.type==='video'){const length=Math.max(.5,Number(m.duration)||.5);px.edit={video:true,start:0,end:length,length,mute:false};}else{const img=await loadImage(m.original||m.blob);px.edit={...blank(),...(m.edit&&m.original?JSON.parse(JSON.stringify(m.edit)):{}),image:img,tab:'adjust',focus:'brightness'};}px.screen='edit';return again();}
 if(a==='phEditCancel'){px.edit=null;px.screen='viewer';return again();}
 if(a==='phEditTab'){px.edit.tab=value;return again();}
 if(a==='phAdj'){px.edit.focus=value;return again();}
 if(a==='phAdjReset'){px.edit.adjust[px.edit.focus]=0;return again();}
 if(a==='phFilter'){px.edit.filter=value;return again();}
 if(a==='phAspect'){px.edit.aspect=value;setAspect(px.edit);return again();}
 if(a==='phRotate'){const e=px.edit;e.rot=(e.rot+1)%4;e.crop={x:0,y:0,w:1,h:1};setAspect(e);return again();}
 if(a==='phFlip'){px.edit.flip=!px.edit.flip;return again();}
 if(a==='phEditDone'){px.sheet={kind:'busy',text:'Saving your edit...',done:.6};again();try{await saveEdit(phone,px);}finally{px.sheet=null;}return again();}
 if(a==='phRevert'){await revert(phone,px);phone.ctx.toast('Back to the original.');return again();}
 if(a==='phTrimPlay'){const v=host.querySelector('[data-pp-trimvideo]');if(v){/* V11.1: a second press pauses */if(!v.paused){v.pause();return;}v.currentTime=px.edit.start;v.play().catch(()=>{});}return;}
 if(a==='phTrimMute'){px.edit.mute=!px.edit.mute;return again();}
 if(a==='phTrimDone'){const e=px.edit;if(e.start<=.02&&e.end>=e.length-.02&&!e.mute){px.edit=null;px.screen='viewer';return again();}try{await saveTrim(phone,px);phone.ctx.toast('Trimmed video saved. The original is kept.');}catch(err){px.sheet=null;phone.ctx.toast(err.message||'The video could not be saved.');}return again();}
